<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Bienvenue — Ambassadors Educational Complex</title><link rel="icon" href="{{ asset('images/logo.png') }}">
    <style>
        :root{--navy:#01082c;--blue:#082b89;--gold:#efbd3f}*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:40px;background:radial-gradient(circle at 75% 15%,#103ba0 0,transparent 34%),linear-gradient(135deg,#01082c,#021346);color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.welcome{width:min(1360px,100%);overflow:hidden;border:1.5px solid var(--gold);border-radius:26px;background:#fff;box-shadow:0 30px 100px #0009}.scene{position:relative;display:flex;align-items:center;min-height:min(720px,76vh);padding:65px 8%;background:linear-gradient(90deg,#03134bf7 0%,#062160d9 48%,#0617478c),url('{{ asset('images/campus.jpg') }}') center/cover}.copy{position:relative;z-index:2;width:min(580px,58%);text-align:center}.logo{width:min(310px,55vw);height:auto;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 12px 20px #00103c)}h1{margin:15px 0 0;font-family:Georgia,serif;font-size:clamp(2rem,3vw,42px);line-height:1.05;overflow-wrap:anywhere}h1 strong{display:block;font-size:clamp(2.7rem,4.6vw,66px)}h1 span{display:block;color:var(--gold);font-size:clamp(2rem,3.3vw,47px)}.rule{display:block;width:110px;height:2px;margin:22px auto;background:var(--gold)}.motto{font-size:20px;line-height:1.5;color:#f3f6ff}.begin{display:inline-flex;align-items:center;justify-content:center;gap:clamp(1.5rem,6vw,65px);max-width:100%;margin-top:12px;padding:18px 34px;border:1px solid #2c6dff;border-radius:10px;background:#0633a8aa;color:#fff;box-shadow:0 0 25px #1762ff88;text-decoration:none;font-size:20px;font-weight:800}.begin span{color:var(--gold);font-size:30px}.values{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:26px 8%;color:#082b89}.value{display:grid;grid-template-columns:65px minmax(0,1fr);align-items:center;gap:20px;padding:0 35px;border-right:1px solid #dfe4ef}.value:last-child{border:0}.icon{display:grid;place-items:center;width:65px;height:65px;border:2px solid #d7ddea;border-radius:50%;font-size:30px}.value strong{display:block;font-size:20px}.value p{margin:5px 0 0;color:#16244e;line-height:1.45}@media(max-width:800px){body{display:block;padding:15px}.scene{min-height:0;padding:40px 20px}.copy{width:100%}.logo{width:min(210px,52vw)}h1{font-size:29px}h1 strong{font-size:43px}h1 span{font-size:31px}.values{grid-template-columns:1fr;gap:20px;padding:25px}.value{border-right:0;border-bottom:1px solid #dfe4ef;padding:0 0 20px}.value:last-child{border:0}.motto{font-size:16px}}@media(max-width:420px){body{padding:8px}.welcome{border-radius:16px}.scene{padding:28px 14px}.logo{width:145px}h1{font-size:23px}h1 strong{font-size:34px}h1 span{font-size:25px}.begin{width:100%;padding:14px 18px;font-size:17px}.values{padding:20px 16px}.value{grid-template-columns:48px minmax(0,1fr);gap:12px}.icon{width:48px;height:48px;font-size:22px}.value strong{font-size:18px}.value p{font-size:14px}}@media(max-height:620px) and (orientation:landscape){body{display:block}.scene{min-height:0;padding-block:24px}.logo{width:120px}.motto{margin-block:8px}.values{padding-block:18px}}
    </style>
</head>
<body><main class="welcome"><section class="scene"><div class="copy"><img class="logo" src="{{ asset('images/logo.png') }}" alt="Logo Ambassadors Educational Complex"><h1>Bienvenue à<strong>Ambassadors</strong><span>Educational Complex</span></h1><i class="rule"></i><p class="motto">Développer les esprits. Bâtir l'avenir.<br>Ensemble dans la Foi, la Vision et la Discipline.</p><a class="begin" href="{{ url('/accueil') }}">Commençons <span>→</span></a></div></section><section class="values"><article class="value"><span class="icon">♢</span><div><strong>Foi</strong><p>Guidés par des valeurs fortes et l'intégrité morale.</p></div></article><article class="value"><span class="icon">◉</span><div><strong>Vision</strong><p>Inspirer les esprits par la connaissance et l'innovation.</p></div></article><article class="value"><span class="icon">★</span><div><strong>Discipline</strong><p>Construire le caractère par l'engagement et la rigueur.</p></div></article></section></main></body>
</html>
